func mod(a, b int64) (int64, error) {
	if b == 0 {
		return 0, eval.ErrDeopt
	}
	r := a % b
	if r != 0 && (r < 0) != (b < 0) {
		r += b
	}
	return r, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	c := a * b
	if c/b != a || a == -1<<63 && b == -1 || b == -1<<63 && a == -1 {
		return 0, eval.ErrDeopt
	}
	return c, nil
}
